"""Exercise 8: a Markdown data dictionary generated by the Inspector."""

import sys

import sqlalchemy as sa

from bazaar.sa.engine import create_engine


def partitions(conn) -> set[str]:
    return set(
        conn.execute(
            sa.text(
                "SELECT relname FROM pg_class WHERE relispartition"
                " AND relnamespace = current_schema()::regnamespace"
            )
        ).scalars()
    )


def data_dictionary(conn: sa.Connection) -> str:
    insp = sa.inspect(conn)
    skip = partitions(conn)
    out = ["# Bazaar data dictionary", ""]
    for table in sorted(set(insp.get_table_names()) - skip):
        comment = insp.get_table_comment(table).get("text") or "*(no comment)*"
        pk = set(insp.get_pk_constraint(table)["constrained_columns"])
        fks = {
            col: f"{fk['referred_table']}.{ref}"
            + (f" ON DELETE {fk['options']['ondelete']}" if fk["options"].get("ondelete") else "")
            for fk in insp.get_foreign_keys(table)
            for col, ref in zip(fk["constrained_columns"], fk["referred_columns"], strict=True)
        }
        out += [f"## {table}", "", comment, ""]
        out += ["| column | type | null | default | key | comment |", "|---|---|---|---|---|---|"]
        for col in insp.get_columns(table):
            if col.get("identity"):
                default = "identity" + (" (always)" if col["identity"]["always"] else "")
            elif col.get("computed"):
                default = "generated"
            else:
                default = (col["default"] or "").replace("|", "\\|")
            key = ", ".join(
                filter(None, ["PK" if col["name"] in pk else "", fks.get(col["name"], "")])
            )
            out.append(
                f"| {col['name']} | {col['type'].compile(conn.dialect).lower()} |"
                f" {'yes' if col['nullable'] else 'no'} | {default} | {key} |"
                f" {col.get('comment') or ''} |"
            )
        out.append("")
    return "\n".join(out)


if __name__ == "__main__":
    engine = create_engine()
    with engine.connect() as conn:
        doc = data_dictionary(conn)
    if len(sys.argv) > 1:
        open(sys.argv[1], "w").write(doc)
    tables = [ln for ln in doc.splitlines() if ln.startswith("## ")]
    print(len(tables), "tables:", ", ".join(t[3:] for t in tables))
    start = doc.index("## orders\n")
    print(doc[start : doc.index("\n## ", start + 1)])
